import React, { useState, useRef, useEffect } from 'react';
import { Header } from './components/common/Header';
import { TabNavigation } from './components/common/TabNavigation';
import { IntervieweeView } from './components/interviewee/IntervieweeView';
import { InterviewerDashboard } from './components/interviewer/InterviewerDashboard';
import { WelcomeBackModal } from './components/modals/WelcomeBackModal';

// Import authentication components
import LandingPage from './components/homepage/LandingPage';
import LoginPage from './components/homepage/LoginPage';
import SignupPage from './components/homepage/SignupPage';

// Import Firebase auth
import { onAuthStateChanged, signOut } from 'firebase/auth';
import { auth } from './firebase';

function App() {
  // Authentication state
  const [authView, setAuthView] = useState('landing');
  const [user, setUser] = useState(null);
  const [authLoading, setAuthLoading] = useState(true);

  // Existing interview state
  const [activeTab, setActiveTab] = useState('interviewee');
  const [candidates, setCandidates] = useState([]);
  const [currentCandidate, setCurrentCandidate] = useState(null);
  const [chatMessages, setChatMessages] = useState([]);
  const [currentInput, setCurrentInput] = useState('');
  const [uploadedFile, setUploadedFile] = useState(null);

  const [interviewStarted, setInterviewStarted] = useState(false);
  const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0);
  const [timeRemaining, setTimeRemaining] = useState(null);
  const [questions, setQuestions] = useState([]);
  const [showWelcomeBack, setShowWelcomeBack] = useState(false);
  const [error, setError] = useState('');
  const [isUploading, setIsUploading] = useState(false);

  const chatEndRef = useRef(null);

  // Listen for Firebase auth state changes
  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, (firebaseUser) => {
      if (firebaseUser) {
        const userData = {
          uid: firebaseUser.uid,
          email: firebaseUser.email,
          name: firebaseUser.displayName || firebaseUser.email.split('@')[0],
          photoURL: firebaseUser.photoURL
        };
        setUser(userData);
        setAuthView('authenticated');
        loadUserInterviewData(firebaseUser.uid);
      } else {
        setUser(null);
        setAuthView('landing');
      }
      setAuthLoading(false);
    });

    return () => unsubscribe();
  }, []);

  const loadUserInterviewData = (userId) => {
    const saved = localStorage.getItem(`interviewData_${userId}`);
    if (saved) {
      const data = JSON.parse(saved);
      if (data.candidates) setCandidates(data.candidates);
      if (data.currentCandidate && !data.currentCandidate.completed) {
        setShowWelcomeBack(true);
      }
    }
  };

  useEffect(() => {
    if (user && authView === 'authenticated') {
      localStorage.setItem(`interviewData_${user.uid}`, JSON.stringify({
        candidates,
        currentCandidate,
        chatMessages,
        interviewStarted,
        currentQuestionIndex,
        questions
      }));
    }
  }, [candidates, currentCandidate, chatMessages, interviewStarted, currentQuestionIndex, questions, user, authView]);

  const handleLogin = (userData) => {
    setUser(userData);
    setAuthView('authenticated');
  };

  const handleSignup = (userData) => {
    setUser(userData);
    setAuthView('authenticated');
  };

  const handleLogout = async () => {
    try {
      await signOut(auth);
      setUser(null);
      setAuthView('landing');
      setCandidates([]);
      setCurrentCandidate(null);
      setChatMessages([]);
      setInterviewStarted(false);
      setCurrentQuestionIndex(0);
      setTimeRemaining(null);
      setQuestions([]);
      setUploadedFile(null);
      setError('');
    } catch (error) {
      console.error('Logout error:', error);
    }
  };

  const addMessage = (sender, content, type = 'text') => {
    setChatMessages(prev => [...prev, { 
      sender, 
      content, 
      type, 
      timestamp: Date.now() 
    }]);
  };

  const handleFileUpload = async (e) => {
    const file = e.target.files[0];
    if (!file) return;

    const fileType = file.name.split('.').pop().toLowerCase();
    if (!['pdf', 'docx'].includes(fileType)) {
      setError('Please upload a PDF or DOCX file');
      return;
    }

    setError('');
    setIsUploading(true);
    setUploadedFile(file);
    addMessage('user', file.name, 'file');
    addMessage('assistant', '🔍 Analyzing your resume...');

    setTimeout(() => {
      const candidateId = `candidate-${Date.now()}`;
      const newCandidate = {
        id: candidateId,
        name: user?.name || 'Candidate',
        email: user?.email || 'email@example.com',
        phone: '+1234567890',
        answers: [],
        completed: false,
        startedAt: Date.now()
      };

      setCurrentCandidate(newCandidate);
      setIsUploading(false);
      addMessage('assistant', `✅ Great! I found your details:\n\n👤 Name: ${newCandidate.name}\n📧 Email: ${newCandidate.email}\n📱 Phone: ${newCandidate.phone}\n\n🚀 Ready to start the interview? Type "start" to begin!`);
    }, 2000);
  };

  const handleSendMessage = () => {
    if (!currentInput.trim()) return;

    addMessage('user', currentInput);
    const input = currentInput.trim();
    setCurrentInput('');

    if (!interviewStarted && input.toLowerCase() === 'start') {
      const sampleQuestions = [
        {
          id: 1,
          question: 'Explain the difference between var, let, and const in JavaScript.',
          difficulty: 'Medium',
          time: 120
        },
        {
          id: 2,
          question: 'What is the Virtual DOM in React?',
          difficulty: 'Easy',
          time: 90
        },
        {
          id: 3,
          question: 'Explain event delegation in JavaScript.',
          difficulty: 'Hard',
          time: 180
        }
      ];

      setQuestions(sampleQuestions);
      setInterviewStarted(true);
      setCurrentQuestionIndex(0);
      setTimeRemaining(sampleQuestions[0].time);
      addMessage('assistant', `🎯 Great! Let's begin. You'll have ${sampleQuestions[0].time} seconds for this question.\n\n**Question 1 (${sampleQuestions[0].difficulty}):**\n${sampleQuestions[0].question}`);
      return;
    }

    if (interviewStarted && currentQuestionIndex < questions.length) {
      handleSubmitAnswer(input);
    }
  };

  const handleSubmitAnswer = (answer) => {
    const answerText = answer || currentInput || '(No answer provided)';
    const question = questions[currentQuestionIndex];
    const score = Math.floor(Math.random() * 10) + 10;

    const newAnswer = {
      questionId: question.id,
      question: question.question,
      answer: answerText,
      score,
      difficulty: question.difficulty,
      timeUsed: question.time - (timeRemaining || 0)
    };

    const updatedAnswers = [...currentCandidate.answers, newAnswer];
    const updatedCandidate = { ...currentCandidate, answers: updatedAnswers };
    setCurrentCandidate(updatedCandidate);

    addMessage('assistant', `✅ Score: ${score}/${question.difficulty === 'Easy' ? 10 : question.difficulty === 'Medium' ? 20 : 30}`);

    if (currentQuestionIndex < questions.length - 1) {
      const nextIndex = currentQuestionIndex + 1;
      const nextQuestion = questions[nextIndex];
      setCurrentQuestionIndex(nextIndex);
      setTimeRemaining(nextQuestion.time);
      addMessage('assistant', `\n**Question ${nextIndex + 1} (${nextQuestion.difficulty}):**\n${nextQuestion.question}\n\n⏱️ You have ${nextQuestion.time} seconds.`);
    } else {
      const totalScore = updatedAnswers.reduce((sum, ans) => sum + ans.score, 0);
      const summary = `Total Score: ${totalScore} points\nQuestions Answered: ${updatedAnswers.length}`;

      const finalCandidate = {
        ...updatedCandidate,
        completed: true,
        summary,
        completedAt: Date.now()
      };

      setCandidates(prev => [...prev, finalCandidate]);
      setCurrentCandidate(null);
      setInterviewStarted(false);
      setTimeRemaining(null);

      addMessage('assistant', `\n🎉 Interview Complete!\n\n${summary}\n\n✨ Thank you for your time! You can now switch to the Interviewer tab to see your results.`);
    }

    setCurrentInput('');
  };

  const handleWelcomeBack = (resume) => {
    setShowWelcomeBack(false);
    if (resume) {
      const saved = localStorage.getItem(`interviewData_${user.uid}`);
      if (saved) {
        const data = JSON.parse(saved);
        if (data.currentCandidate) {
          setCurrentCandidate(data.currentCandidate);
          setChatMessages(data.chatMessages || []);
          setInterviewStarted(data.interviewStarted || false);
          setCurrentQuestionIndex(data.currentQuestionIndex || 0);
          setQuestions(data.questions || []);
          if (data.interviewStarted && data.questions?.[data.currentQuestionIndex]) {
            setTimeRemaining(data.questions[data.currentQuestionIndex].time);
          }
        }
      }
    } else {
      if (user) {
        localStorage.removeItem(`interviewData_${user.uid}`);
      }
      setCurrentCandidate(null);
      setChatMessages([]);
      setInterviewStarted(false);
    }
  };

  if (authLoading) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-blue-50 to-indigo-100 flex items-center justify-center">
        <div className="text-center">
          <div className="w-16 h-16 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin mx-auto mb-4"></div>
          <p className="text-gray-600 font-medium">Loading...</p>
        </div>
      </div>
    );
  }

  if (authView === 'landing') {
    return (
      <LandingPage
        onShowLogin={() => setAuthView('login')}
        onShowSignup={() => setAuthView('signup')}
      />
    );
  }

  if (authView === 'login') {
    return (
      <LoginPage
        onBack={() => setAuthView('landing')}
        onLogin={handleLogin}
      />
    );
  }

  if (authView === 'signup') {
    return (
      <SignupPage
        onBack={() => setAuthView('landing')}
        onSignup={handleSignup}
      />
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-blue-50 to-indigo-100">
      {showWelcomeBack && (
        <WelcomeBackModal
          onResume={() => handleWelcomeBack(true)}
          onStartFresh={() => handleWelcomeBack(false)}
        />
      )}

      <Header user={user} onLogout={handleLogout} />
      <TabNavigation activeTab={activeTab} setActiveTab={setActiveTab} />

      <div className="max-w-7xl mx-auto px-6 pb-8">
        {activeTab === 'interviewee' ? (
          <IntervieweeView
            chatMessages={chatMessages}
            currentInput={currentInput}
            setCurrentInput={setCurrentInput}
            handleSendMessage={handleSendMessage}
            handleFileUpload={handleFileUpload}
            uploadedFile={uploadedFile}
            interviewStarted={interviewStarted}
            timeRemaining={timeRemaining}
            error={error}
            currentCandidate={currentCandidate}
            chatEndRef={chatEndRef}
            isUploading={isUploading}
          />
        ) : (
          <InterviewerDashboard
            candidates={candidates}
          />
        )}
      </div>
    </div>
  );
}

export default App;
